import{z as A,x as d,o as i,c as B,q as r,j as t,D as e,d as n,s,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Diffusion LM 论文","description":"","frontmatter":{"title":"Diffusion LM 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diffusion-lm-paper.md","filePath":"llm/diffusion-lm-paper.md","lastUpdated":1791063341000}'),p={name:"llm/diffusion-lm-paper.md"};function u(f,a,D,h,m,c){const E=d("Mermaid");return i(),B("div",null,[a[2]||(a[2]=r('<h1 id="diffusion-lm-论文" tabindex="-1">Diffusion LM 论文 <a class="header-anchor" href="#diffusion-lm-论文" aria-label="Permalink to &quot;Diffusion LM 论文&quot;">​</a></h1><div class="epigraph"><p>在词嵌入空间做连续扩散，再 round 回离散词，使可控生成能把全局约束写成对嵌入的梯度，而不必从左到右撞墙。</p><footer>—— Li, Thickstun, Gulrajani, Liang, Hashimoto, Diffusion-LM Improves Controllable Text Generation</footer></div><p><a href="/llm/z-loss-paper">z-loss 对照</a> 结束 MoE 数值链。本篇换生成范式：Li、Thickstun、Gulrajani、Liang、Hashimoto 的 <strong>Diffusion-LM</strong>。主干 <a href="/llm/discrete-diffusion-lm">离散扩散</a> 已覆盖掩码吸收等离散核；原文主路径是 <strong>连续嵌入上的高斯扩散 + rounding</strong>，用控制当卖点。附录钉这篇，避免与图像扩散或后世掩码 LM 扩散混名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归可控生成（指定句长、指定要出现的词、句法）很难在已写下的前缀上插入约束。作者把句子表示为词嵌入序列，定义连续前向加噪，训练去噪网络预测干净嵌入，再投影回词表。控制时在连续空间对约束求梯度，更新嵌入再 round。</p><p>问题不是「打败 LM perplexity」，而是控制满足率与流畅度的权衡。似然不是主表。</p><h3 id="rounding-是离散接口" tabindex="-1">Rounding 是离散接口 <a class="header-anchor" href="#rounding-是离散接口" aria-label="Permalink to &quot;Rounding 是离散接口&quot;">​</a></h3><p>连续状态必须变成词。Rounding 不可微，控制循环是「更新连续向量 → 投影」。这与后来直接在词表上定义离散转移的工作不同。</p><p><span class="marginnote">「round 回词表」翻译一下：就是「就近认词」。去噪得到的是一串连续向量，把它们和词表里每个词的嵌入比距离，各挑最近的那个词当输出。这一步像四舍五入，不可求导——所以控制循环只能「在连续向量上算梯度、改完再投影」，不能穿过它反传。</span><span class="marginnote">作者 Xiang Lisa Li、John Thickstun、Ishaan Gulrajani、Percy Liang、Tatsunori Hashimoto。会议 NeurIPS 2022。引用题名 <em>Diffusion-LM Improves Controllable Text Generation</em>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="嵌入加噪、去噪与控制梯度" tabindex="-1">嵌入加噪、去噪与控制梯度 <a class="header-anchor" href="#嵌入加噪、去噪与控制梯度" aria-label="Permalink to &quot;嵌入加噪、去噪与控制梯度&quot;">​</a></h3><p>对嵌入序列 \\(e(x)\\) 加高斯噪声，时间步 \\(t\\) 日程与连续扩散同类。网络 \\(\\epsilon_\\theta\\) 或 \\(x_\\theta\\) 预测。训练目标为嵌入上的回归，不是 token CE 为主（投影后可辅以 CE）。推理从噪声走 \\(T\\) 步，每步可加控制梯度。词表与嵌入维是超参：维太低表达差，太高扩散更难。</p>',12)),(i(),t(l,null,{default:e(()=>[s(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E8%AF%8D%E5%B5%8C%E5%85%A5%E5%BA%8F%E5%88%97%22%5D%20--%3E%20Q%5B%22%E9%AB%98%E6%96%AF%E5%89%8D%E5%90%91%E5%8A%A0%E5%99%AA%22%5D%0A%20%20Q%20--%3E%20NET%5B%22%E5%8E%BB%E5%99%AA%E7%BD%91%E7%BB%9C%22%5D%0A%20%20NET%20--%3E%20R%5B%22round%20%E5%9B%9E%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20CTRL%5B%22%E6%8E%A7%E5%88%B6%E7%BA%A6%E6%9D%9F%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20NET%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[n("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"全局约束在连续空间可写为能量，对所有位置同时作用，这是相对 AR 的结构优势。步数 \\(T\\) 用全序列前向换取可控。流畅度取决于 rounding 是否稳定、嵌入是否与 LM 先验一致。他们常借预训练表示，而不是从零训一个与 GPT 同级的无条件 LM——读实验时要看基座。",-1)),(i(),t(l,null,{default:e(()=>[s(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%EF%BC%9A%E4%BB%8E%E5%B7%A6%E5%88%B0%E5%8F%B3%EF%BC%8C%E7%BA%A6%E6%9D%9F%E9%9A%BE%E6%8F%92%22%5D%0A%20%20%20%20A1%5B%22token%201%22%5D%20--%3E%20A2%5B%22token%202%22%5D%20--%3E%20A3%5B%22token%203%22%5D%20--%3E%20A4%5B%22%E2%80%A6%E2%80%A6%E5%86%99%E5%AE%8C%E6%89%8D%E5%8F%AF%E6%A3%80%E6%9F%A5%22%5D%0A%20%20%20%20A4%20--%3E%20A5%5B%22%E8%BF%9D%E5%8F%8D%E5%85%A8%E5%B1%80%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%8F%AA%E8%83%BD%E6%95%B4%E6%AE%B5%E9%87%8D%E5%86%99%22%5D%0A%20%20end%0A%20%20subgraph%20DF%5B%22Diffusion-LM%EF%BC%9A%E5%85%A8%E5%BA%8F%E5%88%97%E5%90%8C%E6%97%B6%E6%94%B9%22%5D%0A%20%20%20%20B1%5B%22%E6%95%B4%E5%8F%A5%E6%A8%A1%E7%B3%8A%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20B2%5B%22%E5%85%A8%E5%B1%80%E7%BA%A6%E6%9D%9F%E5%86%99%E6%88%90%E8%83%BD%E9%87%8F%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E6%A2%AF%E5%BA%A6%E5%90%8C%E6%97%B6%E6%9B%B4%E6%96%B0%E6%89%80%E6%9C%89%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20%20%20B3%20--%3E%20B4%5B%22round%20%E5%90%8E%E6%A3%80%E6%9F%A5%EF%BC%8C%E4%B8%8D%E6%BB%A1%E8%B6%B3%E5%86%8D%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>与主干离散扩散课的关系：掩码吸收核没有 rounding，控制改成对 logits 的约束。不要用本篇的控制数字证明掩码扩散，也不要反过来。</p><p><span class="marginnote">论文时代的模型尺度远小于当代 AR 推理模型。附录对照的是问题与方法，不是「扩散已在语言上全面优于 AR」。</span></p><p><span class="marginnote">直觉类比：自回归像考试只能从第一格写到最后一个格，中间不许回头，写完才发现漏了要求；扩散式生成像先铺一篇模糊的草稿，所有格子同时修改，约束像一根橡皮筋把整篇慢慢拉向题目要求——「全局」两个字就体现在橡皮筋同时作用在每一个位置上。</span></p><h3 id="对照链往后" tabindex="-1">对照链往后 <a class="header-anchor" href="#对照链往后" aria-label="Permalink to &quot;对照链往后&quot;">​</a></h3><p>ReAct / Toolformer 回到智能体与工具，与扩散无直接继承。本篇在「机制课序对照」里的位置是生成过程：并行去噪 vs 从左到右。读完应能分清 Diffusion-LM 的连续嵌入路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>似然、KV 缓存、流式解码均不占优。产品主对话仍是 AR。Diffusion-LM 适合作为可控生成与编辑的研究原型。嵌入空间扩散对 codec 码的残差层结构无先验，多模态码应走主干课写的结构加噪，而不是直接套本篇。</p><p>复现要锁嵌入是否冻结、控制如何施加、词表。缺一项，满足率不可比。</p><p><span class="marginnote">不要把 Stable Diffusion 的 U-Net 图像栈叫做 Diffusion-LM。状态是文本嵌入序列，不是潜图像。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文在词嵌入上连续扩散，round 回词，服务可控生成。</li><li>主表是控制满足，不是 perplexity 战胜 AR。</li><li>Rounding 与后世离散掩码扩散是不同前向核。</li><li>尺度与产品位置：研究原型，不是对话默认。</li><li>出处：Li 等，Diffusion-LM，NeurIPS 2022。</li></ul>',11))])}const F=A(p,[["render",u]]);export{T as __pageData,F as default};
